// src/backend/services/events.ts
function createEventBus(host, userId) {
  let seq = 0;
  return {
    get lastSeq() {
      return seq;
    },
    emit(event, payload) {
      seq += 1;
      try {
        host.sendToFrontend(createEvent(event, payload, seq), userId);
      } catch {}
    }
  };
}

